const lat = Number(msg.req.query.lat);
const lon = Number(msg.req.query.lon);

if (
    !Number.isFinite(lat) ||
    !Number.isFinite(lon) ||
    lat < -90 ||
    lat > 90 ||
    lon < -180 ||
    lon > 180
) {
    msg.statusCode = 400;

    msg.payload = {
        ok: false,
        mensaje: "Latitud y longitud no vÃ¡lidas"
    };

    return [null, msg];
}

const apiKey = env.get("WEATHER_API_KEY");

if (!apiKey) {
    msg.statusCode = 500;

    msg.payload = {
        ok: false,
        mensaje: "WEATHER_API_KEY no estÃ¡ configurada"
    };

    return [null, msg];
}

msg.latitud = lat;
msg.longitud = lon;

msg.url =
    "https://api.openweathermap.org/data/2.5/weather" +
    "?lat=" + encodeURIComponent(lat) +
    "&lon=" + encodeURIComponent(lon) +
    "&appid=" + encodeURIComponent(apiKey) +
    "&units=metric" +
    "&lang=es";

return [msg, null];

const respuesta = msg.payload;

if (
    !respuesta ||
    !respuesta.main ||
    !respuesta.wind
) {
    const estadoApi =
        msg.statusCode || null;

    msg.statusCode = 502;

    msg.payload = {
        ok: false,
        mensaje: "No se pudo obtener informaciÃ³n meteorolÃ³gica",
        estado_api_clima: estadoApi,
        respuesta_api_clima: respuesta || null
    };

    return msg;
}

const precipitacion =
    respuesta.rain?.["1h"] || 0;

const codigoClima =
    respuesta.weather?.[0]?.id || null;

const descripcionClima =
    respuesta.weather?.[0]?.description || "";

const vientoKmH =
    Number(
        (respuesta.wind.speed * 3.6)
            .toFixed(2)
    );

msg.statusCode = 200;

msg.payload = {
    ok: true,

    latitud: respuesta.coord.lat,
    longitud: respuesta.coord.lon,

    temperatura: respuesta.main.temp,

    velocidad_viento: vientoKmH,

    precipitacion: precipitacion,

    codigo_clima: codigoClima,

    descripcion_clima: descripcionClima,

    fecha_hora_clima:
        new Date(
            respuesta.dt * 1000
        ).toISOString()
};

msg.headers = {
    "Content-Type":
        "application/json; charset=utf-8"
};

return msg;
